import { createRequire } from 'module';
const require = createRequire('/Users/vmysla/.npm/_npx/e41f203b7505f1fb/node_modules/');
const { chromium } = require('playwright-core');
const url = 'file:///Users/vmysla/src/product-tracebility-ab-testing/ab-study/arms/todo-rep-control-02/control/index.html';
const browser = await chromium.launch();
let bad = 0, checks = 0;
for (const tz of ['America/Los_Angeles', 'Etc/GMT+8', 'Pacific/Honolulu', 'Pacific/Kiritimati', 'Europe/London']) {
  for (const day of ['2026-09-13', '2026-03-08', '2026-11-01', '2026-12-31']) {
