      await page.evaluate(() => document.dispatchEvent(new Event('visibilitychange')));
      const r = await page.evaluate(() => [document.querySelector('li').dataset.overdue, new Date().toLocaleDateString('en-CA')]);
      const expected = r[1] > day ? 'true' : 'false';
      checks++;
      if (r[0] !== expected) { bad++; console.log('MISMATCH', tz, day, t.toISOString(), 'local', r[1], 'overdue', r[0]); }
    }
    await ctx.close();
  }
}
